package io.knowledgebrain.activity;
import java.util.*;import org.junit.jupiter.api.*;import org.springframework.mock.web.MockHttpServletRequest;import jakarta.servlet.http.Cookie;import org.springframework.web.server.ResponseStatusException;import org.springframework.http.HttpStatus;import io.micrometer.core.instrument.simple.SimpleMeterRegistry;import static org.mockito.Mockito.*;import static org.junit.jupiter.api.Assertions.*;
class ActivityApiTest extends ActivityFixtures {
 ActivityStore store;ActivityClickHouse index;SpaceAuthorizationClient auth;ActivityController api;UUID space;
 @BeforeEach void init(){space=id();store=mock(ActivityStore.class);index=mock(ActivityClickHouse.class);auth=mock(SpaceAuthorizationClient.class);api=new ActivityController(store,index,auth,new SimpleMeterRegistry());when(store.state()).thenReturn(new ActivityStore.State(true,false,true));when(index.list(eq(space),any())).thenReturn(List.of());}
 MockHttpServletRequest request(){var r=new MockHttpServletRequest("GET","/api/spaces/"+space+"/activity/timeline");r.setSecure(true);r.setCookies(new Cookie("__Host-brain_guest","a".repeat(43)));return r;}
 @Test void eachPageRechecksLivePrivateSpaceAndNeverCaches(){for(int i=0;i<2;i++)assertEquals("no-store",api.timeline(space.toString(),request()).getHeaders().getCacheControl());verify(auth,times(2)).authorize(eq(space),eq("a".repeat(43)),anyString());reset(store,index);when(auth.authorize(eq(space),any(),anyString())).thenThrow(new ResponseStatusException(HttpStatus.NOT_FOUND));assertThrows(ResponseStatusException.class,()->api.timeline(space.toString(),request()));verifyNoInteractions(store,index);}
 @Test void projectionRecoveryReturns503AndPageUsesDescendingEventCursor(){when(store.state()).thenReturn(new ActivityStore.State(true,true,false));assertEquals(503,assertThrows(ResponseStatusException.class,()->api.timeline(space.toString(),request())).getStatusCode().value());verifyNoInteractions(index);when(store.state()).thenReturn(new ActivityStore.State(true,false,true));var a=ActivityEvent.decode(ActivityEvent.TOPICS.get("ROADMAP"),wire("ROADMAP",space));when(index.list(eq(space),any())).thenReturn(List.of(a,a));var r=request();r.addParameter("limit","1");var p=api.timeline(space.toString(),r).getBody();assertEquals(1,p.items().size());assertNotNull(p.nextBefore());assertEquals("EVENTUAL",p.consistency());}
 @Test void unsafeOrAmbiguousRequestsFailBeforeAnyPrivateRead(){var body=request();body.setContent("{}".getBytes());var dup=request();dup.addParameter("kind","ALL","ROADMAP");var http=request();http.setSecure(false);var cookie=request();cookie.setCookies(new Cookie("__Host-brain_guest","a".repeat(43)),new Cookie("__Host-brain_guest","b".repeat(43)));for(var r:List.of(body,dup,http,cookie))assertThrows(ResponseStatusException.class,()->api.timeline(space.toString(),r));verifyNoInteractions(store,index,auth);}
}
